'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const money=v=>new Intl.NumberFormat('es-CO',{style:'currency',currency:'COP',maximumFractionDigits:0}).format(Number(v)||0);
const number=v=>new Intl.NumberFormat('es-CO',{maximumFractionDigits:3}).format(Number(v)||0);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=n=>`<svg class="icon" aria-hidden="true"><use href="#i-${n}"/></svg>`;
const badge=(t,c='neutral')=>`<span class="pill ${c}"><span class="dot"></span>${esc(t)}</span>`;
const TZ='America/Bogota',cfg=window.VERDELIA_CONFIG;
const dateKey=(v=new Date())=>new Intl.DateTimeFormat('en-CA',{timeZone:TZ,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(v));
const dateLabel=v=>new Intl.DateTimeFormat('es-CO',{timeZone:TZ,day:'2-digit',month:'short',year:'numeric'}).format(new Date(v));
const timeLabel=v=>new Intl.DateTimeFormat('es-CO',{timeZone:TZ,hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(new Date(v));
const dateAt=d=>new Date(d+'T12:00:00-05:00');
const categories=['Frutas','Verduras','Minimarket','Lácteos','Alimento para mascotas','Limpieza','Golosinas','Panadería','Arepas y empanadas','Jugos','Salpicón y ensaladas de frutas','Bebidas','Abarrotes','Congelados','Combos','Otros'];
const methods={efectivo:'Efectivo',transferencia:'Transferencia',tarjeta:'Tarjeta'};
const orderLabels={pending:'Pendiente',confirmed:'Confirmado',completed:'Entregado',cancelled:'Cancelado'};
let session=localStorage.getItem('verdelia.session')||'',state={products:[],sales:[],orders:[],cash:[],stock_moves:[],lots:[],purchases:[],closings:[],audit:[],balances:{},settings:{name:'Verdélia',whatsapp:'573115565525',pound_grams:500},preferences:{}},catalog={products:[],settings:{}},page='resumen',from=dateKey(),to=dateKey(),calendarMonth=dateKey().slice(0,7),query='',category='Todas',onlyLow=false,saleChannel='Todos',saleMethod='Todos',salesPage=0,orderFilter='Todos',storeCategory='Todos',storeQuery='',cart=[],lastFocus,loading=false,formLines=[],draftSaleId='',requestInFlight=false,activationToken='',reportCache={};
const product=id=>state.products.find(p=>p.id===id);
const allCategories=()=>[...new Set([...categories,...state.products.map(p=>p.category)])];
const periodText=()=>from===to?(from===dateKey()?'Hoy':dateLabel(dateAt(from))):`${dateLabel(dateAt(from))} — ${dateLabel(dateAt(to))}`;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4500)}
function offline(){const el=$('#connection');el.hidden=navigator.onLine;el.textContent='Sin conexión. Los movimientos no se guardan hasta que vuelvas a conectarte.'}
window.addEventListener('offline',offline);window.addEventListener('online',()=>{offline();if(session)loadData().catch(showError)});
async function rpc(name,args){if(!navigator.onLine)throw new Error('No hay conexión. No se registró el movimiento.');const ctl=new AbortController(),timer=setTimeout(()=>ctl.abort(),30000);try{const res=await fetch(cfg.url+'/rest/v1/rpc/'+name,{method:'POST',headers:{'Content-Type':'application/json',apikey:cfg.key},body:JSON.stringify(args),signal:ctl.signal});let d=await res.json();if(!res.ok){if(d.code==='42501'){localStorage.removeItem('verdelia.session');session='';}throw new Error(d.message||'No fue posible completar la operación.')}if(d?.error)throw new Error(d.error);return d}catch(e){if(e.name==='AbortError')throw new Error('La conexión tardó demasiado. Puedes reintentar; el movimiento no se duplicará.');throw e}finally{clearTimeout(timer)}}
function showError(e){console.error(e.message);toast(e.message);if(!session&&page!=='tienda')render()}
async function loadData(a=from,b=to){state=await rpc('verdelia_admin',{action:'snapshot',data:{session,from:a,to:b}});reportCache[a+'|'+b]=state;return state}
async function loadCatalog(){catalog=await rpc('verdelia_catalog',{});return catalog}
async function mutate(action,data,form){if(requestInFlight)return;requestInFlight=true;if(form)form.classList.add('busy');try{const request_id=form?(form.dataset.requestId||=crypto.randomUUID()):crypto.randomUUID();const result=await rpc('verdelia_admin',{action,data:{...data,request_id,session}});await loadData();if(page==='calendario')await calendarLoad();requestInFlight=false;closeDrawer();render();toast('Guardado correctamente.');return result}catch(e){showError(e)}finally{requestInFlight=false;if(form)form.classList.remove('busy')}}
function header(title,sub,actions=''){return `<section class="heading between"><div><div class="eyebrow">Tu negocio, en orden</div><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="actions flex">${actions}</div></section>`}
function empty(title,text,button=''){return `<div class="empty"><span class="muted">${icon('box')}</span><h2>${title}</h2><p>${text}</p>${button}</div>`}
function nav(){const isPublic=page==='tienda',isAuth=['activar','recuperar'].includes(page)||!session;$('#shell').classList.toggle('public',isPublic);const links=[['resumen','Resumen'],['ventas','Ventas'],['calendario','Calendario'],['inventario','Inventario'],['combos','Combos'],['pedidos','Pedidos'],['caja','Caja'],['link','Link de venta']];$('.nav').innerHTML=!isAuth&&!isPublic?links.map(([id,n])=>`<a href="#${id}" ${page===id?'class="active" aria-current="page"':''}>${n}</a>`).join(''):'';$('#account').innerHTML=isPublic?`<button class="btn" onclick="document.getElementById('cart-panel').scrollIntoView({behavior:'smooth'})">${icon('bag')}Mi pedido</button>`:session?`<a href="#ajustes" class="iconbtn" aria-label="Ajustes y automatizaciones">${icon('clock')}</a><button class="iconbtn" aria-label="Alertas" onclick="alertDrawer()">${icon('bell')}</button><button class="textbtn" onclick="logout()">Salir</button>`:`<a href="#tienda" class="btn">Ver catálogo ${icon('arrow')}</a>`}
async function route(){closeDrawer();const hash=location.hash.slice(1)||'resumen';page=hash.split('?')[0];if(page==='activar'){activationToken=new URLSearchParams(hash.split('?')[1]).get('token')||activationToken;if(activationToken)history.replaceState(null,'',location.pathname+'#activar')}
 if(!['resumen','ventas','calendario','inventario','combos','pedidos','caja','link','tienda','ajustes','activar','recuperar'].includes(page))page='resumen';nav();$('#main').innerHTML='<div class="empty"><span class="loader"></span><p>Cargando…</p></div>';
 try{if(page==='tienda'||page==='link')await loadCatalog();if(session&&page!=='tienda'&&page!=='activar'&&page!=='recuperar'){if(page==='calendario'){await calendarLoad()}else if(!state.server_time)await loadData()}render();if(page==='ajustes'&&session)loadAutomation();window.scrollTo(0,0);const action=new URLSearchParams(hash.split('?')[1]).get('accion');if(session&&action){if(action==='venta')saleForm();if(action==='gasto')cashForm();if(action==='cierre')closeCashForm();if(action==='reposicion')replenish()}}catch(e){$('#main').innerHTML=empty('No pudimos cargar esta vista',esc(e.message),'<button class="btn" onclick="route()">Reintentar</button>');showError(e)}}
function render(){nav();if(page==='activar'){$('#main').innerHTML=authPage('activate');return}if(page==='recuperar'){$('#main').innerHTML=authPage('recover');return}if(page!=='tienda'&&!session){$('#main').innerHTML=authPage('login');return}$('#main').innerHTML=({resumen:overview,ventas:salesView,calendario:calendarView,inventario:inventoryView,combos:combosView,pedidos:ordersView,caja:cashView,link:storeView,tienda:storeView,ajustes:settingsView}[page])();document.title=`Verdélia · ${page==='tienda'?'Link de venta':page.charAt(0).toUpperCase()+page.slice(1)}`}
function authPage(mode){const activate=mode==='activate',recover=mode==='recover';return `<div class="login-wrap"><section class="card"><div class="eyebrow">Acceso privado</div><h1>${activate?'Activa Verdélia':recover?'Recuperar acceso':'Bienvenido a Verdélia'}</h1><p class="subtitle">${activate?'Define tu contraseña para empezar.':recover?'Utiliza el código de recuperación que guardaste al activar tu cuenta.':'Tus ventas, inventario y cuentas, en un solo lugar.'}</p><form onsubmit="authSubmit(event,'${mode}')">${mode==='login'?'<label class="field">Usuario<input name="username" autocomplete="username" value="verdelia" required></label>':''}${recover?'<label class="field">Código de recuperación<input name="token" autocomplete="off" required></label>':''}<label class="field">${mode==='login'?'Contraseña':'Nueva contraseña'}<input name="password" type="password" autocomplete="${mode==='login'?'current-password':'new-password'}" minlength="${mode==='login'?1:10}" required ${mode!=='login'?'placeholder="Al menos 10 caracteres"':''}></label>${mode!=='login'?'<label class="field">Repite tu contraseña<input name="confirm" type="password" autocomplete="new-password" minlength="10" required></label>':''}<div class="form-error" id="auth-error" hidden></div><button class="btn primary" type="submit">${activate?'Activar mi cuenta':recover?'Cambiar contraseña':'Entrar'} ${icon('arrow')}</button></form>${mode==='login'?'<a class="textbtn" style="margin-top:16px" href="#recuperar">Olvidé mi contraseña</a>':'<a class="textbtn" style="margin-top:16px" href="#resumen">Volver al inicio</a>'}<p class="lock-note">Acceso exclusivo del administrador. Las cuentas no son visibles en el catálogo.</p></section></div>`}
async function authSubmit(e,action){e.preventDefault();const f=e.target,d=Object.fromEntries(new FormData(f)),btn=f.querySelector('button');if(action!=='login'&&d.password!==d.confirm){$('#auth-error').hidden=false;$('#auth-error').textContent='Las contraseñas no coinciden.';return}btn.disabled=true;try{if(action==='activate')d.token=activationToken;const r=await rpc('verdelia_login',{action,data:d});session=r.session;localStorage.setItem('verdelia.session',session);activationToken='';state.server_time=null;await loadData();page='resumen';history.replaceState(null,'',location.pathname+'#resumen');render();if(r.recovery_code)showRecovery(r.recovery_code)}catch(err){$('#auth-error').hidden=false;$('#auth-error').textContent=err.message}finally{btn.disabled=false}}
function showRecovery(code){openDrawer('Guarda tu código de recuperación',`<p class="desc">Este código permite recuperar tu acceso. Guárdalo en un lugar privado; no se mostrará de nuevo.</p><div class="recovery-code" style="margin-top:20px">${esc(code)}</div><div class="drawerfoot"><button class="btn" onclick="downloadText('verdelia-recuperacion.txt',this.dataset.code)" data-code="${esc(code)}">${icon('download')}Guardar código</button><button class="btn primary" onclick="closeDrawer()">Ya lo guardé</button></div>`)}
async function logout(){const device=localStorage.getItem('verdelia.pushDevice');if(device){try{await automationCall('unsubscribe',{id:device});localStorage.removeItem('verdelia.pushDevice');const reg=await navigator.serviceWorker.getRegistration();await(await reg?.pushManager.getSubscription())?.unsubscribe()}catch{toast('No se pudo desactivar este dispositivo. Puedes hacerlo desde Ajustes.')}}try{await rpc('verdelia_login',{action:'logout',data:{session}})}catch{}session='';localStorage.removeItem('verdelia.session');state.server_time=null;render()}
function financial(data){const sales=data.sales||[],cash=data.cash||[],moves=data.stock_moves||[];const revenue=sales.reduce((n,s)=>n+Number(s.total),0),cost=sales.reduce((n,s)=>n+Number(s.cost),0),expenses=-cash.filter(x=>x.kind==='expense').reduce((n,x)=>n+Number(x.amount),0),losses=-moves.filter(x=>x.reason==='loss').reduce((n,x)=>n+Number(x.quantity)*Number(x.unit_cost),0);return{revenue,cost,expenses,losses,profit:revenue-cost-expenses-losses,count:sales.filter(s=>s.type==='sale').length,refunds:-sales.filter(s=>s.type==='refund').reduce((n,s)=>n+Number(s.total),0)}}
function dateFilters(){return `<div class="date-filters"><label>Desde<input id="date-from" type="date" value="${from}"></label><label>Hasta<input id="date-to" type="date" value="${to}"></label><button class="btn primary" onclick="applyDates()">Aplicar</button><button class="btn" onclick="quickDates('today')">Hoy</button><button class="btn" onclick="quickDates('week')">7 días</button><button class="btn" onclick="quickDates('month')">Este mes</button></div>`}
async function applyDates(a,b){const f=a||$('#date-from').value,t=b||$('#date-to').value;if(!f||!t||f>t){toast('Selecciona un rango de fechas válido.');return}const prev=[from,to];from=f;to=t;salesPage=0;try{await loadData();render()}catch(e){[from,to]=prev;showError(e)}}
function quickDates(type){const d=dateAt(dateKey());if(type==='week')d.setDate(d.getDate()-6);if(type==='month')d.setDate(1);applyDates(dateKey(d),dateKey())}
function stockLow(){return state.products.filter(p=>p.kind==='product'&&p.active&&Number(p.stock)-Number(p.reserved)<=Number(p.minimum))}
function stockBadge(p){return Number(p.available)<=0?badge('Agotado','danger'):Number(p.available)<=Number(p.minimum)?badge('Bajo','warning'):badge('Disponible','positive')}
function overview(){const f=financial(state),local=state.sales.filter(s=>s.channel==='local').reduce((n,s)=>n+Number(s.total),0),online=f.revenue-local,low=stockLow();return `${header('Así va Verdélia',periodText(),`<a href="#ventas" class="btn">Ver informe</a><button class="btn primary" onclick="saleForm()">${icon('plus')}Nueva venta</button>`)}${dateFilters()}<div class="summary-grid"><section class="card sales-card"><div class="cardhead"><h2 class="label-icon">${icon('wallet')}Ventas netas</h2>${badge(f.count+' ventas')}</div><div class="amount num">${money(f.revenue)}</div><p class="small muted">Ventas cobradas menos devoluciones del período.</p><div class="sales-bottom"><div class="metric-mini"><span class="small muted">En el local</span><strong>${money(local)}</strong></div><div class="metric-mini"><span class="small muted">Por internet</span><strong>${money(online)}</strong></div><a href="#calendario" class="btn" style="margin-left:auto">Calendario ${icon('arrow')}</a></div></section><section class="card profit-card"><div class="cardhead"><h2>Ganancia estimada</h2>${icon('chart')}</div><div class="amount num">${money(f.profit)}</div><p class="small muted">Después de costos, gastos y pérdidas.</p><div class="profit-footer"><div class="profit-cell">Costo de lo vendido<strong>${money(f.cost)}</strong></div><div class="profit-cell">Gastos y pérdidas<strong>${money(f.expenses+f.losses)}</strong></div></div></section></div><div class="row2"><section class="card"><div class="cardhead"><h2>Ventas por día</h2><a href="#ventas" class="textbtn">Detalle ${icon('arrow')}</a></div>${salesChart(state.sales)}</section><section class="card"><div class="cardhead"><h2>Para reponer</h2>${badge(low.length+' productos','warning')}</div>${low.length?low.slice(0,3).map(p=>`<div class="stockrow"><div class="initial">${esc(p.name.slice(0,2))}</div><div class="stock-info"><p>${esc(p.name)}</p><small>${number(p.available)} ${p.unit} disponibles</small></div><strong class="small">${money(Math.max(0,p.target-p.available)*p.avg_cost)}</strong></div>`).join(''):'<p class="muted small">No hay productos por debajo del mínimo.</p>'}<div class="cardfoot"><span>Estimado <strong>${money(low.reduce((n,p)=>n+Math.max(0,p.target-p.available)*p.avg_cost,0))}</strong></span><button class="textbtn" onclick="replenish()">Ver lista ${icon('arrow')}</button></div></section></div><div class="bottom-grid"><section class="card table-card"><div class="cardhead"><h2>Últimas operaciones</h2><a href="#ventas" class="textbtn">Ver todas</a></div>${salesTable(state.sales.slice(0,5),true)}</section><section class="card"><div class="cardhead"><h2>Tu operación</h2><button class="textbtn" onclick="alertDrawer()">Ver alertas</button></div><div class="detail-row"><span>Pedidos pendientes</span><strong>${state.orders.filter(o=>o.status==='pending').length}</strong></div><div class="detail-row"><span>Pedidos en preparación</span><strong>${state.orders.filter(o=>o.status==='confirmed').length}</strong></div><div class="detail-row"><span>Dinero disponible</span><strong>${money(Object.values(state.balances).reduce((a,b)=>a+Number(b),0))}</strong></div><div class="detail-row"><span>Productos publicados</span><strong>${state.products.filter(p=>p.published&&p.active).length}</strong></div></section></div>`}
function groupDays(sales){const map={};sales.forEach(s=>map[dateKey(s.created_at)]=(map[dateKey(s.created_at)]||0)+Number(s.total));return map}
function salesChart(sales){const days=groupDays(sales),keys=Object.keys(days).sort(),max=Math.max(1,...Object.values(days));if(!keys.length)return empty('Aún no hay ventas','Las ventas registradas aparecerán aquí.');return `<div class="daily-chart" role="img" aria-label="Ventas netas por día">${keys.map(d=>`<button class="daily-bar" title="${d}: ${money(days[d])}" onclick="showDay('${d}')"><i style="height:${Math.max(2,days[d]/max*100)}%"></i><span>${d.slice(8)}/${d.slice(5,7)}</span></button>`).join('')}</div><p class="status-line">Toca una barra para abrir las operaciones de ese día.</p>`}
function filteredSales(){return state.sales.filter(s=>(saleChannel==='Todos'||s.channel===saleChannel)&&(saleMethod==='Todos'||s.method===saleMethod))}
function salesView(){const sales=filteredSales(),f=financial({...state,sales});return `${header('Ventas al detalle','Fecha, hora, productos y resultado de cada operación.',`<button class="btn" onclick="exportSales()">${icon('download')}Exportar</button><button class="btn primary" onclick="saleForm()">${icon('plus')}Nueva venta</button>`)}${dateFilters()}<div class="toolbar"><div class="report-filters"><select class="select" aria-label="Canal de venta" onchange="saleChannel=this.value;salesPage=0;render()">${[['Todos','Todos los canales'],['local','Local'],['internet','Internet']].map(([v,n])=>`<option value="${v}" ${saleChannel===v?'selected':''}>${n}</option>`).join('')}</select><select class="select" aria-label="Medio de pago" onchange="saleMethod=this.value;salesPage=0;render()">${[['Todos','Todos los pagos'],...Object.entries(methods)].map(([v,n])=>`<option value="${v}" ${saleMethod===v?'selected':''}>${n}</option>`).join('')}</select></div><span class="small muted">Hora de Colombia · ${periodText()}</span></div><div class="stats-strip"><div class="stat-small"><p>Ventas netas</p><strong>${money(f.revenue)}</strong></div><div class="stat-small"><p>Ganancia bruta</p><strong>${money(f.revenue-f.cost)}</strong></div><div class="stat-small"><p>Operaciones de venta</p><strong>${f.count}</strong></div><div class="stat-small"><p>Dinero devuelto</p><strong>${money(f.refunds)}</strong></div></div><div class="chart-layout"><section class="card"><div class="cardhead"><h2>Ventas por fecha</h2></div>${salesChart(sales)}</section><section class="card"><div class="cardhead"><h2>Medios de pago</h2></div>${Object.entries(methods).map(([m,n])=>`<div class="detail-row"><span>${n}</span><strong>${money(sales.filter(s=>s.method===m).reduce((v,s)=>v+Number(s.total),0))}</strong></div>`).join('')}<p class="status-line">Incluye las devoluciones en su fecha real.</p></section></div><section class="card table-card" style="padding-top:0">${salesTable(sales.slice(salesPage*25,(salesPage+1)*25))}<div class="pagination"><span>${sales.length} operaciones · Página ${salesPage+1}</span><div class="flex"><button class="btn" ${salesPage===0?'disabled':''} onclick="salesPage--;render()">Anterior</button><button class="btn" ${(salesPage+1)*25>=sales.length?'disabled':''} onclick="salesPage++;render()">Siguiente</button></div></div></section>`}
function salesTable(sales,compact=false){if(!sales.length)return empty('Sin operaciones en este período','Registra una venta o selecciona otras fechas.');return `<div class="table-wrap"><table><thead><tr><th>Operación</th><th>Fecha y hora</th>${compact?'':'<th>Cliente / canal</th><th>Pago</th>'}<th>Total</th>${compact?'':'<th>Ganancia bruta</th>'}<th>Tipo</th></tr></thead><tbody>${sales.map(s=>`<tr><td><button class="textbtn" onclick="saleDetail('${s.id}')">VD-${s.number} ${icon('arrow')}</button></td><td class="date-cell">${dateLabel(s.created_at)}<small>${timeLabel(s.created_at)}</small></td>${compact?'':`<td>${esc(s.customer||'Mostrador')}<div class="small muted">${s.channel==='local'?'Local':'Internet'}</div></td><td>${methods[s.method]}</td>`}<td class="strong ${s.type==='refund'?'negative-text':''}">${money(s.total)}</td>${compact?'':`<td>${money(s.total-s.cost)}</td>`}<td>${s.type==='refund'?badge('Devolución','warning'):badge(s.status==='refunded'?'Venta devuelta':'Venta',s.status==='refunded'?'neutral':'positive')}</td></tr>`).join('')}</tbody></table></div>`}
let calendarState=null;
async function calendarLoad(){const first=calendarMonth+'-01',d=dateAt(first);d.setMonth(d.getMonth()+1);d.setDate(0);calendarState=await rpc('verdelia_admin',{action:'report',data:{session,from:first,to:dateKey(d)}})}
async function changeMonth(n){const d=dateAt(calendarMonth+'-01');d.setMonth(d.getMonth()+n);calendarMonth=dateKey(d).slice(0,7);try{await calendarLoad();render()}catch(e){showError(e)}}
function dayData(d,source=calendarState||state){return{sales:source.sales.filter(x=>dateKey(x.created_at)===d),cash:source.cash.filter(x=>dateKey(x.created_at)===d),stock_moves:source.stock_moves.filter(x=>dateKey(x.created_at)===d)}}
function calendarView(){const src=calendarState||state,f=financial(src),first=dateAt(calendarMonth+'-01'),start=(first.getDay()+6)%7,end=dateAt(calendarMonth+'-01');end.setMonth(end.getMonth()+1);end.setDate(0);const length=end.getDate(),cells=[];for(let i=0;i<start;i++)cells.push('<div class="cal-blank"></div>');for(let day=1;day<=length;day++){const d=calendarMonth+'-'+String(day).padStart(2,'0'),v=financial(dayData(d,src)),has=v.count||v.expenses||v.losses||v.refunds||dayData(d,src).cash.length;cells.push(`<button class="cal-day ${d===dateKey()?'today':''} ${has?'has-data':''}" onclick="showDay('${d}')" aria-label="${d}, ventas ${money(v.revenue)}, gastos ${money(v.expenses)}, ganancia ${money(v.profit)}"><span class="cal-date">${day}</span>${has?`<div class="cal-value"><span>Ventas</span><strong>${money(v.revenue)}</strong></div><div class="cal-value"><span>Gastos</span><strong>${money(v.expenses)}</strong></div><div class="cal-value"><span>Ganancia</span><strong class="${v.profit<0?'negative-text':'positive-text'}">${money(v.profit)}</strong></div>`:'<span class="small muted">—</span>'}</button>`)}while(cells.length%7)cells.push('<div class="cal-blank"></div>');return `${header('Calendario financiero','Toca cualquier día para ver qué vendiste, gastaste y ganaste.')}<div class="stats-strip"><div class="stat-small"><p>Ventas del mes</p><strong>${money(f.revenue)}</strong></div><div class="stat-small"><p>Gastos del mes</p><strong>${money(f.expenses)}</strong></div><div class="stat-small"><p>Pérdidas del mes</p><strong>${money(f.losses)}</strong></div><div class="stat-small"><p>Ganancia estimada</p><strong>${money(f.profit)}</strong></div></div><div class="between" style="margin-bottom:20px"><h2 class="calendar-title">${new Intl.DateTimeFormat('es-CO',{month:'long',year:'numeric',timeZone:TZ}).format(first)}</h2><div class="flex"><button class="btn" onclick="changeMonth(-1)" aria-label="Mes anterior">←</button><button class="btn" onclick="calendarMonth=dateKey().slice(0,7);calendarLoad().then(render).catch(showError)">Este mes</button><button class="btn" onclick="changeMonth(1)" aria-label="Mes siguiente">→</button></div></div><section class="card calendar-card"><div class="calendar-scroll"><div class="calendar-head">${['Lunes','Martes','Miércoles','Jueves','Viernes','Sábado','Domingo'].map(x=>`<span data-short="${x.slice(0,2)}">${x}</span>`).join('')}</div><div class="calendar-grid">${cells.join('')}</div></div></section><div class="calendar-legend"><span>Ganancia = ventas − costo vendido − gastos − pérdidas.</span><span>Compras de inventario y retiros se consultan como salidas de dinero.</span></div>`}
async function showDay(d){try{const src=await rpc('verdelia_admin',{action:'report',data:{session,from:d,to:d}});const f=financial(src);openDrawer(dateLabel(dateAt(d)),`<p class="desc">Operaciones del día · Hora de Colombia</p><div class="stats-strip" style="grid-template-columns:1fr 1fr;margin-top:20px"><div class="stat-small"><p>Ventas</p><strong>${money(f.revenue)}</strong></div><div class="stat-small"><p>Ganancia estimada</p><strong>${money(f.profit)}</strong></div><div class="stat-small"><p>Gastos</p><strong>${money(f.expenses)}</strong></div><div class="stat-small"><p>Pérdidas</p><strong>${money(f.losses)}</strong></div></div><h2>Ventas y devoluciones</h2>${src.sales.length?src.sales.map(s=>`<div class="history-item between"><div><button class="textbtn" onclick="saleDetailData(this.dataset.sale)" data-sale="${esc(JSON.stringify(s))}">VD-${s.number}</button><small> · ${timeLabel(s.created_at)}</small><p>${methods[s.method]} · ${s.channel==='local'?'Local':'Internet'}</p></div><strong>${money(s.total)}</strong></div>`).join(''):'<p class="subtitle">No hubo ventas.</p>'}<h2 style="margin-top:22px">Entradas y salidas de dinero</h2>${src.cash.map(c=>`<div class="history-item between"><div><p>${esc(c.note||c.category||c.kind)}</p><small>${timeLabel(c.created_at)} · ${methods[c.method]}</small></div><strong class="${c.amount<0?'negative-text':'positive-text'}">${money(c.amount)}</strong></div>`).join('')||'<p class="subtitle">No hubo movimientos de dinero.</p>'}<h2 style="margin-top:22px">Movimientos de inventario</h2>${src.stock_moves.map(m=>`<div class="history-item between"><div><p>${esc(product(m.product_id)?.name||'Producto')} · ${({opening:'Inventario inicial',purchase:'Compra',sale:'Venta',refund:'Devolución',loss:'Pérdida',adjustment:'Ajuste'})[m.reason]||esc(m.reason)}</p><small>${timeLabel(m.created_at)}${m.note?' · '+esc(m.note):''}</small></div><strong>${number(m.quantity)} ${esc(product(m.product_id)?.unit||'')}</strong></div>`).join('')||'<p class="subtitle">No hubo movimientos de inventario.</p>'}<div class="drawerfoot"><button class="btn primary" onclick="closeDrawer();location.hash='ventas';applyDates('${d}','${d}')">Ver informe del día</button></div>`)}catch(e){showError(e)}}
function inventoryView(){const ps=state.products.filter(p=>p.kind==='product');return `${header('Inventario','Productos organizados por categoría, con precios y existencias reales.',`<button class="btn" onclick="receiveForm()">${icon('plus')}Recibir compra</button><button class="btn primary" onclick="productForm()">${icon('plus')}Producto</button>`)}<div class="stats-strip"><div class="stat-small"><p>Productos</p><strong>${ps.filter(p=>p.active).length}</strong></div><div class="stat-small"><p>Valor al costo</p><strong>${money(ps.reduce((n,p)=>n+p.stock*p.avg_cost,0))}</strong></div><div class="stat-small"><p>Por reponer</p><strong>${stockLow().length}</strong></div><div class="stat-small"><p>Reservas para pedidos</p><strong>${state.orders.filter(o=>o.status==='confirmed').length}</strong></div></div><div class="toolbar"><label class="search">${icon('search')}<input aria-label="Buscar producto" value="${esc(query)}" placeholder="Buscar producto o código…" oninput="query=this.value;$('#product-table').innerHTML=productTable()"></label><div class="flex wrap"><select class="select" aria-label="Categoría" onchange="category=this.value;$('#product-table').innerHTML=productTable()">${['Todas',...allCategories()].map(c=>`<option ${c===category?'selected':''}>${esc(c)}</option>`).join('')}</select><button class="btn" onclick="onlyLow=!onlyLow;render()">${onlyLow?'Mostrar todos':'Stock bajo'}</button><button class="btn" onclick="replenish()">Lista de compra</button></div></div><section class="card table-card" style="padding-top:0" id="product-table">${productTable()}</section>`}
function productTable(){const ps=state.products.filter(p=>p.kind==='product'&&(p.name+' '+p.sku).toLowerCase().includes(query.toLowerCase())&&(category==='Todas'||p.category===category)&&(!onlyLow||p.available<=p.minimum));if(!ps.length)return empty('No hay productos para mostrar',state.products.length?'Prueba otra categoría o búsqueda.':'Añade el primer producto para comenzar.',`<button class="btn primary" onclick="productForm()">${icon('plus')}Añadir producto</button>`);return `<div class="table-wrap"><table><thead><tr><th>Producto</th><th>Categoría</th><th>Precio costo</th><th>Precio venta</th><th>Disponible / reservado</th><th>Estado</th><th>Catálogo</th><th></th></tr></thead><tbody>${ps.map(p=>`<tr><td><div class="product-name">${p.image_url?`<img class="image-thumb" src="${esc(p.image_url)}" alt="" loading="lazy">`:`<div class="initial">${esc(p.name.slice(0,2))}</div>`}<div><strong>${esc(p.name)}</strong><small>${esc(p.sku||'Sin código')} · ${p.unit}</small></div></div></td><td>${esc(p.category)}</td><td>${money(p.avg_cost)} / ${p.unit}</td><td>${money(p.price)} / ${p.unit}</td><td>${number(p.available)} / <span class="muted">${number(p.reserved)}</span><small class="muted"> ${p.unit}</small></td><td>${p.active?stockBadge(p):badge('Inactivo')}</td><td>${p.published&&p.active?'Publicado':'Oculto'}</td><td><button class="textbtn" onclick="productForm('${p.id}')">Editar</button><button class="textbtn" style="margin-left:10px" onclick="stockForm('${p.id}')">Movimiento</button></td></tr>`).join('')}</tbody></table></div>`}
function comboCost(p){return Number(p.avg_cost)+(p.recipe||[]).reduce((n,r)=>n+Number(r.quantity)*Number(product(r.product_id)?.avg_cost||0),0)}
function combosView(){const cs=state.products.filter(p=>p.kind==='combo');return `${header('Combos y preparados','Recetas que descuentan sus ingredientes del mismo inventario.',`<button class="btn primary" onclick="productForm(null,true)">${icon('plus')}Crear receta</button>`)}<div class="banner">${icon('box')}Configura combos de frutas, jugos, salpicón o empanadas con sus ingredientes y empaque.</div>${cs.length?`<div class="combo-grid">${cs.map(c=>`<article class="combo-card"><div class="combo-art">${badge(c.active&&c.available>0?'Disponible':'Sin disponibilidad',c.active&&c.available>0?'positive':'danger')}${c.image_url?`<img src="${esc(c.image_url)}" alt="${esc(c.name)}" style="width:100%;height:100%;object-fit:cover">`:'<svg aria-hidden="true"><use href="#fruit-art"/></svg>'}</div><div class="combo-content"><h2>${esc(c.name)}</h2><p>${esc(c.category)} · ${c.recipe.length} ingredientes</p><div class="combo-price">${money(c.price)} <small>por unidad</small></div><div class="combo-finance"><div><span>Costo actual</span><strong>${money(comboCost(c))}</strong></div><div><span>Ganancia bruta</span><strong>${money(c.price-comboCost(c))}</strong></div></div><div class="between"><span class="small muted">${number(c.available)} disponibles</span><button class="btn" onclick="productForm('${c.id}',true)">Editar receta</button></div></div></article>`).join('')}</div>`:empty('Crea tu primer combo o preparado','Los ingredientes deben estar registrados en el inventario.',`<button class="btn primary" onclick="productForm(null,true)">Crear receta</button>`)}`}
function ordersView(){const orders=state.orders.filter(o=>orderFilter==='Todos'||o.status===orderFilter);return `${header('Pedidos de clientes','Revisa, reserva, cobra y entrega los pedidos del Link de venta.')}<div class="tabs-line">${[['Todos','Todos'],...Object.entries(orderLabels)].map(([id,n])=>`<button class="${orderFilter===id?'active':''}" onclick="orderFilter='${id}';render()">${n}</button>`).join('')}</div><section class="card table-card" style="padding-top:0">${orders.length?`<div class="table-wrap"><table><thead><tr><th>Pedido</th><th>Fecha y hora</th><th>Cliente</th><th>Entrega</th><th>Total estimado</th><th>Estado</th><th></th></tr></thead><tbody>${orders.map(o=>`<tr><td>P-${o.number}</td><td class="date-cell">${dateLabel(o.created_at)}<small>${timeLabel(o.created_at)}</small></td><td>${esc(o.customer)}<div class="small muted">${esc(o.phone)}</div></td><td>${o.delivery_type==='pickup'?'Recogida':'Domicilio'}</td><td>${money(o.quote.total)}</td><td>${badge(orderLabels[o.status],o.status==='pending'?'warning':o.status==='completed'?'positive':'neutral')}</td><td><button class="textbtn" onclick="orderDetail('${o.id}')">Abrir ${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div>`:empty('No hay pedidos en este estado','Comparte tu Link de venta para comenzar a recibirlos.')}</section><p class="subtitle">Los pendientes no reservan inventario. Al confirmar se reserva; al cobrar y entregar se registra la venta.</p>`}
function cashView(){const f=financial(state);return `${header('Caja y cuentas',periodText(),`<button class="btn" onclick="cashForm()">${icon('plus')}Movimiento</button><button class="btn primary" onclick="closeCashForm()">Cerrar caja</button>`)}${dateFilters()}<div class="cash-layout"><section class="card cash-balance"><h2>Dinero disponible</h2><div class="amount">${money(Object.values(state.balances).reduce((n,v)=>n+Number(v),0))}</div><p class="muted small">Acumulado de todos los movimientos registrados.</p><div class="divider" style="background:#ffffff30"></div>${Object.entries(methods).map(([id,n])=>`<div class="cash-item"><span>${n}</span><strong>${money(state.balances[id]||0)}</strong></div>`).join('')}</section><section class="card"><div class="cardhead"><h2>Resultado del período</h2><a href="#calendario" class="textbtn">Ver calendario</a></div><div class="detail-row"><span>Ventas netas</span><strong>${money(f.revenue)}</strong></div><div class="detail-row"><span>Costo de lo vendido</span><strong>${money(f.cost)}</strong></div><div class="detail-row"><span>Gastos operativos</span><strong>${money(f.expenses)}</strong></div><div class="detail-row"><span>Pérdidas de inventario</span><strong>${money(f.losses)}</strong></div><div class="between" style="margin-top:22px"><h2>Ganancia estimada</h2><strong class="strongtotal">${money(f.profit)}</strong></div></section></div><section class="card table-card" style="margin-top:20px"><div class="cardhead"><h2>Entradas y salidas</h2><button class="textbtn" onclick="exportCash()">Exportar ${icon('download')}</button></div>${state.cash.length?`<div class="table-wrap"><table><thead><tr><th>Fecha y hora</th><th>Concepto</th><th>Tipo</th><th>Medio</th><th class="right">Valor</th></tr></thead><tbody>${state.cash.map(c=>`<tr><td class="date-cell">${dateLabel(c.created_at)}<small>${timeLabel(c.created_at)}</small></td><td>${esc(c.note||c.category)}</td><td>${({sale:'Venta',refund:'Devolución',purchase:'Compra',expense:'Gasto',deposit:'Aporte',withdrawal:'Retiro'})[c.kind]}</td><td>${methods[c.method]}</td><td class="right ${c.amount<0?'negative-text':'positive-text'}">${money(c.amount)}</td></tr>`).join('')}</tbody></table></div>`:empty('Sin movimientos','Registra la base de caja como aporte para comenzar.')}</section><section class="card" style="margin-top:20px"><div class="cardhead"><h2>Cierres de caja</h2></div>${state.closings.slice(0,10).map(c=>`<div class="detail-row"><span>${dateLabel(c.created_at)} · ${timeLabel(c.created_at)}</span><div>Contado: ${money(c.counted)} · Diferencia: <strong>${money(c.difference)}</strong></div></div>`).join('')||'<p class="muted">Todavía no hay cierres registrados.</p>'}<p class="status-line">El cierre conserva la diferencia; no altera automáticamente el saldo.</p></section>`}
function openDrawer(title,content){lastFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="backdrop" onclick="if(event.target===this)closeDrawer()"><section class="drawer" role="dialog" aria-modal="true" aria-labelledby="drawer-title"><div class="between drawerhead"><h2 id="drawer-title">${title}</h2><button class="iconbtn" aria-label="Cerrar panel" onclick="closeDrawer()">${icon('close')}</button></div>${content}</section></div>`;document.body.style.overflow='hidden';$('.drawerhead button').focus()}
function closeDrawer(){if(requestInFlight)return;$('#modal-root').innerHTML='';document.body.style.overflow='';if(lastFocus?.isConnected)lastFocus.focus()}
document.addEventListener('keydown',e=>{const d=$('.drawer');if(!d)return;if(e.key==='Escape')closeDrawer();if(e.key==='Tab'){const a=[...d.querySelectorAll('button:not(:disabled),a[href],input:not([hidden]),select,textarea')].filter(x=>x.offsetParent!==null),f=a[0],l=a[a.length-1];if(e.shiftKey&&document.activeElement===f){e.preventDefault();l.focus()}else if(!e.shiftKey&&document.activeElement===l){e.preventDefault();f.focus()}}});
function field(label,name,type='text',value='',extra=''){return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`}
function selectField(label,name,options,value,extra=''){return `<label class="field">${label}<select name="${name}" ${extra}>${options.map(o=>{const [v,n]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(n)}</option>`}).join('')}</select></label>`}
function check(label,name,value){return `<label class="form-check"><input type="checkbox" name="${name}" ${value?'checked':''}>${label}</label>`}
function formData(f){return Object.fromEntries(new FormData(f))}
function buttons(label='Guardar'){return `<div class="drawerfoot"><button class="btn" type="button" onclick="closeDrawer()">Cancelar</button><button class="btn primary" type="submit">${label}</button></div>`}
const unitNames={kg:'Kilos disponibles',und:'Unidades disponibles',paquete:'Paquetes disponibles',botella:'Botellas disponibles',bandeja:'Bandejas disponibles',litro:'Litros disponibles'};
function priceMeasures(unit){return unit==='kg'?[['kg','Por kilo'],['lb','Por libra'],['g','Por gramo']]:[[unit,'Por '+({und:'unidad',paquete:'paquete',botella:'botella',bandeja:'bandeja',litro:'litro'}[unit]||unit)]]}
function productForm(id=null,isCombo=false){
 const p=product(id)||{name:'',sku:'',category:isCombo?'Combos':'Frutas',unit:isCombo?'und':'kg',price:'',avg_cost:'',stock:0,minimum:0,target:0,active:true,published:true,description:'',image_url:'',recipe:[]};
 isCombo=isCombo||p.kind==='combo';formLines=(p.recipe||[]).map(r=>({id:r.product_id,quantity:Number(r.quantity)}));
 openDrawer(id?'Editar '+(isCombo?'receta':'producto'):'Añadir '+(isCombo?'receta':'producto'),`<form id="product-form" onsubmit="saveProduct(event,'${id||''}',${isCombo})">
 ${field('Nombre','name','text',p.name,'required maxlength="100"')}${field('Código (opcional)','sku','text',p.sku,'maxlength="40"')}
 ${selectField('Categoría','category_choice',[...allCategories().map(c=>[c,c]),['__custom__','＋ Crear otra categoría']],p.category,'onchange="toggleCustomCategory(this.value)"')}<label class="field" id="custom-category-field" hidden>Nueva categoría<input name="custom_category" maxlength="100" placeholder="Escribe el nombre…" disabled></label>

 ${!isCombo?selectField('Cómo llevas el inventario','unit',[['kg','Kilos (también vende libras y gramos)'],['und','Unidades'],['paquete','Paquetes'],['botella','Botellas'],['bandeja','Bandejas'],['litro','Litros']],p.unit,'onchange="productUnitChanged(this.value)"'):''}
 <div class="fields2"><div>${field('Precio costo','cost','number',p.avg_cost,'required min="0" max="999999999" step="0.0001" inputmode="decimal" oninput="productPriceHint()"')}${!isCombo?selectField('Medida del precio costo','cost_unit',priceMeasures(p.unit),p.unit,'onchange="convertProductPrice(this,\'cost\')"'):'<p class="form-hint">Empaque por receta. Los ingredientes se calculan aparte.</p>'}</div><div>${field('Precio venta','price','number',p.price,'required min="0" max="999999999" step="0.0001" inputmode="decimal" oninput="productPriceHint()"')}${!isCombo?selectField('Medida del precio venta','price_unit',priceMeasures(p.unit),p.unit,'onchange="convertProductPrice(this,\'price\')"'):''}</div></div>
 <p class="form-hint" id="product-price-hint" aria-live="polite"></p>${!isCombo?`<fieldset class="price-suggestions"><legend>Precio venta sugerido</legend><p class="form-hint">Elige cuánto aumentar sobre el precio costo.</p><div class="suggestion-options">${[30,40,50].map(pct=>`<button class="btn" type="button" data-markup="${pct}" onclick="applySuggestedPrice(${pct})"><span>+${pct}%</span><strong data-suggested-price="${pct}">—</strong></button>`).join('')}</div><div class="custom-markup"><label class="field">Otro aumento (%)<input type="number" name="markup_percent" min="0" max="1000" step="0.1" inputmode="decimal" placeholder="Ej. 35"></label><button type="button" class="btn" onclick="applySuggestedPrice()">Usar porcentaje</button></div><p class="form-hint">Puedes cambiar el precio venta manualmente antes de guardar.</p></fieldset>`:''}
 ${!isCombo?`${field(unitNames[p.unit],id?'stock_count':'opening_stock','number',p.stock,'required min="0" max="1000000" step="0.001" inputmode="decimal"')}<div class="fields2">${field('Avisar al llegar a','minimum','number',p.minimum,'required min="0" step="0.001"')}${field('Reponer hasta','target','number',p.target,'required min="0" step="0.001"')}</div><p class="form-hint" id="stock-unit-hint">Existencias y niveles en ${p.unit==='kg'?'kilos':p.unit}. Las compras actualizan el precio costo promedio.</p>${id?field('Motivo de la corrección (si cambias costo, medida o cantidad)','note','text','','maxlength="500" placeholder="Ej. Corregí el costo de compra…"')+ '<p class="form-hint">Las ventas anteriores conservan su precio y costo. La cantidad corregida queda registrada como ajuste.</p>':''}`:`<h2 style="margin:20px 0 8px">Ingredientes por unidad</h2><div id="recipe-lines"></div><button class="textbtn" type="button" onclick="formLines.push({id:'',quantity:1});renderRecipe()">${icon('plus')}Añadir ingrediente</button>`}
 ${field('Enlace HTTPS de la foto (opcional)','image_url','url',p.image_url,'placeholder="https://…"')}<label class="field">Descripción<textarea name="description" maxlength="1000">${esc(p.description)}</textarea></label>${check('Mostrar en el Link de venta','published',p.published)}${id?check('Producto activo','active',p.active):''}${buttons(id?'Guardar cambios':'Crear '+(isCombo?'receta':'producto'))}</form>`);
 if(isCombo){if(!formLines.length)formLines=[{id:'',quantity:1}];renderRecipe()}else{for(const name of ['cost_unit','price_unit'])$('#product-form').elements[name].dataset.previous=p.unit;productPriceHint()}
}
function toggleCustomCategory(value){const label=$('#custom-category-field'),input=label.querySelector('input'),custom=value==='__custom__';label.hidden=!custom;input.disabled=!custom;input.required=custom;if(custom)input.focus()}
function productUnitChanged(unit){const f=$('#product-form');for(const key of ['cost_unit','price_unit']){f.elements[key].innerHTML=priceMeasures(unit).map(([v,n])=>`<option value="${v}">${n}</option>`).join('');f.elements[key].dataset.previous=unit}const input=f.elements.stock_count||f.elements.opening_stock;input.closest('label').childNodes[0].textContent=unitNames[unit];$('#stock-unit-hint').textContent=`Existencias y niveles en ${unit==='kg'?'kilos':unit}. Las compras actualizan el precio costo promedio.`;productPriceHint()}
function convertProductPrice(select,name){const f=$('#product-form'),p={unit:f.elements.unit.value},before=select.dataset.previous||p.unit,value=Number(f.elements[name].value);if(f.elements[name].value!=='')f.elements[name].value=+(value/factor(p,before)*factor(p,select.value)).toFixed(4);select.dataset.previous=select.value;productPriceHint()}
function suggestedSalePrice(cost,costUnit,priceUnit,baseUnit,percent){const p={unit:baseUnit};return Math.round(Number(cost)/factor(p,costUnit)*factor(p,priceUnit)*(1+Number(percent)/100)*100)/100}
function productPriceHint(){const f=$('#product-form'),target=$('#product-price-hint');if(!target||!f.elements.unit)return;const p={unit:f.elements.unit.value};const cost=Number(f.elements.cost.value)/factor(p,f.elements.cost_unit.value),price=Number(f.elements.price.value)/factor(p,f.elements.price_unit.value);target.textContent=p.unit==='kg'?`Por kilo: costo ${money(cost)} · venta ${money(price)}. Una libra = ${number(state.settings.pound_grams)} g.`:'Valores en pesos colombianos.';for(const el of $$('[data-suggested-price]')){el.textContent=money(suggestedSalePrice(f.elements.cost.value,f.elements.cost_unit.value,f.elements.price_unit.value,p.unit,el.dataset.suggestedPrice));el.closest('button').disabled=f.elements.cost.value===''}}
function applySuggestedPrice(percent){const f=$('#product-form');if(!f||!f.elements.unit)return;if(percent===undefined){if(f.elements.markup_percent.value===''){toast('Escribe el porcentaje de aumento.');return}percent=Number(f.elements.markup_percent.value)}if(!Number.isFinite(percent)||percent<0||percent>1000){toast('Usa un porcentaje entre 0 y 1000.');return}if(f.elements.cost.value===''){toast('Primero escribe el precio costo.');return}f.elements.price.value=suggestedSalePrice(f.elements.cost.value,f.elements.cost_unit.value,f.elements.price_unit.value,f.elements.unit.value,percent);productPriceHint();toast(`Precio venta calculado con ${number(percent)}% de aumento.`)}
function renderRecipe(){$('#recipe-lines').innerHTML=formLines.map((l,i)=>`<div class="line-item" style="grid-template-columns:1fr 100px 30px"><label class="field">Ingrediente<select required onchange="formLines[${i}].id=this.value"><option value="">Selecciona…</option>${state.products.filter(p=>p.kind==='product'&&p.active).map(p=>`<option value="${p.id}" ${p.id===l.id?'selected':''}>${esc(p.name)} (${p.unit})</option>`).join('')}</select></label><label class="field">Cantidad base<input type="number" min="0.001" step="0.001" required value="${l.quantity}" oninput="formLines[${i}].quantity=+this.value"></label><button type="button" aria-label="Quitar ingrediente" onclick="formLines.splice(${i},1);renderRecipe()">${icon('close')}</button></div>`).join('')}
async function saveProduct(e,id,isCombo){e.preventDefault();const f=e.target,d=formData(f);d.category=d.category_choice==='__custom__'?d.custom_category.trim():d.category_choice;delete d.category_choice;delete d.custom_category;d.id=id||null;if(id)d.expected_updated_at=product(id).updated_at;d.kind=isCombo?'combo':'product';d.unit=isCombo?'und':d.unit;d.active=id?f.elements.active.checked:true;d.published=f.elements.published.checked;if(isCombo){formLines=$$('#recipe-lines .line-item').map(row=>({id:row.querySelector('select').value,quantity:Number(row.querySelector('input').value)}));const merged={};for(const r of formLines){if(!r.id||r.quantity<=0){toast('Revisa los ingredientes y cantidades.');return}merged[r.id]=(merged[r.id]||0)+Number(r.quantity)}d.recipe=Object.entries(merged).map(([id,quantity])=>({id,quantity}));d.minimum=0;d.target=0}await mutate('save_product',d,f)}
function stockForm(id){const p=product(id),moves=state.stock_moves.filter(m=>m.product_id===id).slice(0,12);openDrawer('Movimiento · '+esc(p.name),`<p class="desc">Disponible: ${number(p.available)} ${p.unit}. Reservado: ${number(p.reserved)} ${p.unit}.</p><form style="margin-top:20px" onsubmit="stockSubmit(event,'${id}')">${selectField('Tipo de movimiento','reason',[['loss','Pérdida o vencimiento'],['subtract','Ajuste: disminuir'],['add','Ajuste: aumentar']],'loss')}${field('Cantidad en '+p.unit,'quantity','number','','min="0.001" max="1000000" step="0.001" required')}${field('Motivo','note','text','','required minlength="3" maxlength="500"')}${buttons('Registrar movimiento')}</form><h2 style="margin-top:25px">Movimientos recientes</h2>${moves.map(m=>`<div class="history-item between"><div><p>${({opening:'Inventario inicial',purchase:'Compra',sale:'Venta',refund:'Devolución',loss:'Pérdida',adjustment:'Ajuste'})[m.reason]}</p><small>${dateLabel(m.created_at)} ${timeLabel(m.created_at)}</small><p class="small muted">${esc(m.note)}</p></div><strong>${number(m.quantity)} ${p.unit}</strong></div>`).join('')||'<p class="subtitle">No hay movimientos en el período consultado.</p>'}`)}
async function stockSubmit(e,id){e.preventDefault();const f=e.target,d=formData(f);d.id=id;d.quantity=Number(d.quantity)*(d.reason==='add'?1:-1);d.reason=d.reason==='loss'?'loss':'adjustment';await mutate('adjust_stock',d,f)}
function receiveForm(){formLines=[{id:'',quantity:1,unit_cost:0,expiry:''}];openDrawer('Recibir una compra',`<p class="desc">La compra aumenta existencias, actualiza el costo promedio y registra la salida de dinero.</p><form style="margin-top:20px" onsubmit="receiveSubmit(event)">${field('Proveedor','supplier','text','','maxlength="150"')}<div id="receive-lines"></div><button class="textbtn" type="button" onclick="formLines.push({id:'',quantity:1,unit_cost:0,expiry:''});renderReceive()">${icon('plus')}Otro producto</button>${selectField('Pagado con','method',Object.entries(methods),'efectivo')}${field('Nota (opcional)','note','text','','maxlength="500"')}<div class="between"><span>Total de compra</span><strong class="sale-amount" id="purchase-total">$0</strong></div>${buttons('Registrar compra pagada')}</form>`);renderReceive()}
function renderReceive(){$('#receive-lines').innerHTML=formLines.map((l,i)=>`<section class="sale-line"><div class="line-item purchase-line"><label class="field">Producto<select required onchange="formLines[${i}].id=this.value;formLines[${i}].unit_cost=Number(product(this.value)?.avg_cost||0);renderReceive()"><option value="">Selecciona…</option>${state.products.filter(p=>p.kind==='product').map(p=>`<option value="${p.id}" ${l.id===p.id?'selected':''}>${esc(p.name)} (${p.unit})</option>`).join('')}</select></label><label class="field">Cantidad<input required type="number" min="0.001" step="0.001" value="${l.quantity}" oninput="formLines[${i}].quantity=+this.value;purchaseTotal()"></label><label class="field">Costo / medida<input required type="number" min="0" step="0.01" value="${l.unit_cost}" oninput="formLines[${i}].unit_cost=+this.value;purchaseTotal()"></label><button type="button" aria-label="Quitar línea" onclick="formLines.splice(${i},1);renderReceive()">${icon('close')}</button></div><label class="field" style="margin-top:8px">Vencimiento (opcional)<input type="date" value="${l.expiry}" oninput="formLines[${i}].expiry=this.value"></label></section>`).join('');purchaseTotal()}
function purchaseTotal(){$('#purchase-total').textContent=money(formLines.reduce((n,l)=>n+l.quantity*l.unit_cost,0))}
async function receiveSubmit(e){e.preventDefault();formLines=$$('#receive-lines .sale-line').map(row=>({id:row.querySelector('select').value,quantity:Number(row.querySelectorAll('input')[0].value),unit_cost:Number(row.querySelectorAll('input')[1].value),expiry:row.querySelector('input[type=date]').value}));if(!formLines.length||formLines.some(l=>!l.id||l.quantity<=0)){toast('Revisa los productos de la compra.');return}await mutate('receive',{...formData(e.target),lines:formLines},e.target)}
function saleForm(){if(!state.products.some(p=>p.active)){toast('Primero añade productos al inventario.');return}formLines=[];openDrawer('Nueva venta',`<form id="sale-form" onsubmit="saleSubmit(event)"><p class="desc" style="margin-bottom:20px">Se registra con fecha y hora actuales. Confirma el pago antes de guardar.</p><label class="field">Añadir producto<select onchange="addSaleLine(this.value);this.value='' "><option value="">Selecciona un producto…</option>${state.products.filter(p=>p.active).map(p=>`<option value="${p.id}" ${p.available<=0?'disabled':''}>${esc(p.name)} · ${money(p.price)}/${p.unit} ${p.available<=0?'(agotado)':''}</option>`).join('')}</select></label><div id="sale-lines"></div><div class="fields2">${field('Descuento (COP)','discount','number',0,'min="0" step="1" oninput="saleTotal()"')}${field('Domicilio cobrado (COP)','delivery','number',0,'min="0" step="1" oninput="saleTotal()"')}</div>${selectField('Medio de pago','method',Object.entries(methods),'efectivo')}${field('Efectivo recibido (opcional)','cash_received','number','','min="0" step="1"')}${field('Cliente (opcional)','customer','text','','maxlength="100"')}<div class="between"><span>Total a cobrar</span><strong class="sale-amount" id="sale-total">$0</strong></div>${buttons('Registrar venta cobrada')}</form>`);renderSaleLines()}
function addSaleLine(id){if(!id)return;const p=product(id);formLines.push({id,quantity:1,unit:p.unit});renderSaleLines()}
function factor(p,unit){return p.unit==='kg'?(unit==='lb'?Number(state.settings.pound_grams)/1000:unit==='g'?.001:1):1}
function renderSaleLines(){$('#sale-lines').innerHTML=formLines.length?formLines.map((l,i)=>{const p=product(l.id);return `<div class="line-item"><div><h3>${esc(p.name)}</h3><small class="muted">${money(p.price)} / ${p.unit}</small></div><label class="field">Cantidad<input aria-label="Cantidad de ${esc(p.name)}" type="number" min="0.001" step="0.001" required value="${l.quantity}" oninput="formLines[${i}].quantity=+this.value;saleTotal()"></label><label class="field">Medida<select onchange="formLines[${i}].unit=this.value;saleTotal()">${(p.unit==='kg'?['kg','lb','g']:[p.unit]).map(u=>`<option ${u===l.unit?'selected':''}>${u}</option>`).join('')}</select></label><button type="button" aria-label="Quitar producto" onclick="formLines.splice(${i},1);renderSaleLines()">${icon('close')}</button></div>`}).join(''):'<div class="empty" style="padding:20px">Añade el primer producto.</div>';saleTotal()}
function saleTotal(){const f=$('#sale-form'),sub=formLines.reduce((n,l)=>n+Math.round(Number(product(l.id).price)*factor(product(l.id),l.unit)*l.quantity*100)/100,0);$('#sale-total').textContent=money(sub-Number(f.elements.discount.value||0)+Number(f.elements.delivery.value||0))}
async function saleSubmit(e){e.preventDefault();if(!formLines.length){toast('Añade al menos un producto.');return}const lineNodes=$$('#sale-lines .line-item');formLines=formLines.map((l,i)=>({...l,quantity:Number(lineNodes[i].querySelector('input').value),unit:lineNodes[i].querySelector('select').value}));const r=await mutate('sale',{...formData(e.target),lines:formLines,channel:'local'},e.target);if(r)saleDetailData(r)}
function saleDetail(id){const s=state.sales.find(s=>s.id===id);if(s)saleDetailData(s)}
function saleDetailData(raw){const s=typeof raw==='string'?JSON.parse(raw):raw;openDrawer((s.type==='refund'?'Devolución':'Venta')+' VD-'+s.number,`<div class="invoice"><div class="brand"><span class="brand-mark"><svg><use href="#i-leaf"/></svg></span>${esc(state.settings.name||'Verdélia')}</div><p class="invoice-note">${esc(state.settings.address||'Fruver y minimarket')}<br>WhatsApp: ${esc(state.settings.whatsapp)}</p><div class="divider"></div><div class="between"><strong>VD-${s.number}</strong><span>${s.type==='refund'?'Devolución':'Comprobante de venta'}</span></div><p class="small muted">${dateLabel(s.created_at)} · ${timeLabel(s.created_at)} · Colombia</p><p style="margin-top:10px">Cliente: ${esc(s.customer||'Consumidor final')}<br>Pago: ${methods[s.method]} · ${s.channel==='local'?'Local':'Internet'}</p><table style="margin-top:14px"><thead><tr><th>Producto</th><th>Cantidad</th><th class="right">Valor</th></tr></thead><tbody>${s.lines.map(l=>`<tr><td>${esc(l.name)}</td><td>${number(l.quantity)} ${l.unit}</td><td class="right">${money(l.subtotal)}</td></tr>`).join('')}</tbody></table><div class="detail-row"><span>Subtotal</span><strong>${money(s.subtotal)}</strong></div><div class="detail-row"><span>Descuento</span><strong>${money(s.discount)}</strong></div><div class="detail-row"><span>Domicilio</span><strong>${money(s.delivery)}</strong></div><div class="detail-row"><span>Total</span><strong>${money(s.total)}</strong></div>${s.method==='efectivo'&&s.cash_received!=null?`<div class="detail-row"><span>Cambio</span><strong>${money(s.cash_received-s.total)}</strong></div>`:''}<p class="invoice-note">Comprobante de control interno. No es factura electrónica.<br>Gracias por comprar en Verdélia.</p></div><div class="receipt-actions"><button class="btn" onclick="window.print()">Imprimir / PDF</button><button class="btn" onclick="shareReceipt(this.dataset.sale)" data-sale="${esc(JSON.stringify(s))}">Compartir</button></div><section class="card no-print"><h2>Detalle interno</h2><div class="detail-row"><span>Costo histórico</span><strong>${money(s.cost)}</strong></div><div class="detail-row"><span>Ganancia bruta</span><strong>${money(s.total-s.cost)}</strong></div><p class="small muted">Los cambios posteriores de precio no alteran esta operación.</p></section>${s.type==='sale'&&s.status==='paid'?`<div class="drawerfoot"><button class="btn" onclick="refundForm('${s.id}')">Registrar devolución total</button></div>`:''}`)}
function refundForm(id){openDrawer('Devolución total',`<p class="desc">Se conservará la venta original y se registrará la devolución del dinero con fecha y hora actuales.</p><form style="margin-top:20px" onsubmit="refundSubmit(event,'${id}')">${field('Motivo de la devolución','note','text','','required minlength="3" maxlength="500"')}${check('La mercancía está apta y vuelve al inventario','restock',false)}<p class="form-hint">El empaque consumido conserva su costo. Una mercancía dañada no debe volver a existencias.</p>${buttons('Confirmar devolución total')}</form>`)}
async function refundSubmit(e,id){e.preventDefault();await mutate('refund',{id,note:e.target.elements.note.value,restock:e.target.elements.restock.checked},e.target)}
function cashForm(){openDrawer('Movimiento de dinero',`<form onsubmit="cashSubmit(event)">${selectField('Tipo','kind',[['expense','Gasto del negocio'],['deposit','Aporte / base de caja'],['withdrawal','Retiro del dueño']],'expense')}${field('Concepto','note','text','','required minlength="3" maxlength="500"')}${selectField('Categoría','category',['Transporte','Arriendo','Servicios','Empaques','Personal','Mantenimiento','Otros'],'Otros')}<div class="fields2">${field('Valor (COP)','amount','number','','required min="1" max="999999999" step="1"')}${selectField('Medio','method',Object.entries(methods),'efectivo')}</div><p class="small muted">Para comprar mercancía usa Recibir compra. Así también se actualiza el inventario.</p>${buttons('Registrar movimiento')}</form>`)}
async function cashSubmit(e){e.preventDefault();await mutate('cash',formData(e.target),e.target)}
function closeCashForm(){const expected=Number(state.balances.efectivo||0);openDrawer('Cerrar caja de hoy',`<p class="desc">${dateLabel(new Date())}. El cierre conserva el saldo esperado y la diferencia.</p><div class="detail-list"><div class="detail-row"><span>Efectivo esperado</span><strong>${money(expected)}</strong></div></div><form onsubmit="closeCashSubmit(event)">${field('Efectivo contado (COP)','counted','number','','required min="0" step="1" oninput="document.getElementById(\'cash-diff\').textContent=money(Number(this.value)-'+expected+')"')}<div class="detail-row"><span>Diferencia</span><strong id="cash-diff">—</strong></div>${field('Observaciones','note','text','','maxlength="500"')}${buttons('Guardar cierre')}</form>`)}
async function closeCashSubmit(e){e.preventDefault();await mutate('close_cash',formData(e.target),e.target)}
function orderDetail(id){const o=state.orders.find(o=>o.id===id);openDrawer('Pedido P-'+o.number,`${badge(orderLabels[o.status],o.status==='pending'?'warning':'neutral')}<div class="detail-list"><div class="detail-row"><span>Recibido</span><strong>${dateLabel(o.created_at)} ${timeLabel(o.created_at)}</strong></div><div class="detail-row"><span>Cliente</span><strong>${esc(o.customer)}</strong></div><div class="detail-row"><span>Teléfono</span><a href="https://wa.me/${encodeURIComponent(o.phone)}" target="_blank" rel="noopener noreferrer">${esc(o.phone)} ${icon('diagonal')}</a></div><div class="detail-row"><span>Entrega</span><strong>${o.delivery_type==='pickup'?'Recogida':esc(o.address)}</strong></div>${o.quote.lines.map(l=>`<div class="detail-row"><span>${esc(l.name)} · ${number(l.quantity)} ${l.unit}</span><strong>${money(l.subtotal)}</strong></div>`).join('')}<div class="detail-row"><span>Domicilio</span><strong>${money(o.quote.delivery)}</strong></div><div class="detail-row"><span>Total</span><strong>${money(o.quote.total)}</strong></div></div>${o.note?`<p class="desc">${esc(o.note)}</p>`:''}${o.status==='pending'?`<form onsubmit="orderAction(event,'confirm_order','${id}')">${buttons('Confirmar y reservar')}</form>`:''}${o.status==='confirmed'?`<form onsubmit="orderAction(event,'complete_order','${id}')">${selectField('Pago recibido por','method',Object.entries(methods),'efectivo')}<p class="small muted">Al confirmar se registra el cobro y la entrega, y se descuentan los ingredientes reservados.</p>${buttons('Cobrar y marcar entregado')}</form>`:''}${['pending','confirmed'].includes(o.status)?`<button class="textbtn" style="margin-top:20px;color:var(--red)" onclick="cancelOrderForm('${id}')">Cancelar pedido</button>`:''}${o.confirmed_at?`<p class="status-line">Confirmado: ${dateLabel(o.confirmed_at)} ${timeLabel(o.confirmed_at)}</p>`:''}${o.completed_at?`<p class="status-line">Entregado: ${dateLabel(o.completed_at)} ${timeLabel(o.completed_at)}</p>`:''}`)}
async function orderAction(e,action,id){e.preventDefault();const r=await mutate(action,{...formData(e.target),id},e.target);if(r&&action==='complete_order')saleDetailData(r)}
function cancelOrderForm(id){openDrawer('Cancelar pedido',`<form onsubmit="orderAction(event,'cancel_order','${id}')">${field('Motivo','note','text','','required minlength="3" maxlength="500"')}<p class="small muted">Se liberarán las reservas. No se eliminará el historial.</p>${buttons('Cancelar pedido')}</form>`)}
function replenish(){const rows=stockLow();openDrawer('Lista de reposición',`<p class="desc">Cantidades para llegar al objetivo. Presupuesto calculado al costo promedio registrado.</p><div class="detail-list">${rows.map(p=>`<div class="detail-row"><div><strong>${esc(p.name)}</strong><p class="small muted">${number(Math.max(0,p.target-p.available))} ${p.unit} × ${money(p.avg_cost)}</p></div><strong>${money(Math.max(0,p.target-p.available)*p.avg_cost)}</strong></div>`).join('')||'<p class="subtitle">No hay productos para reponer.</p>'}</div><div class="between"><span>Inversión estimada</span><strong class="sale-amount">${money(rows.reduce((n,p)=>n+Math.max(0,p.target-p.available)*p.avg_cost,0))}</strong></div><p class="status-line">Confirma el precio con el proveedor antes de comprar.</p><div class="drawerfoot"><button class="btn" onclick="exportReplenishment()">${icon('download')}Descargar lista</button><button class="btn primary" onclick="receiveForm()">Registrar compra</button></div>`)}
function alertDrawer(){const low=state.preferences.stock?stockLow():[],end=dateAt(dateKey());end.setDate(end.getDate()+Number(state.preferences.expiry_days??3));const lots=state.preferences.expiry?state.lots.filter(l=>l.expiry<=dateKey(end)):[],orders=state.preferences.pending_orders?state.orders.filter(o=>o.status==='pending'):[];openDrawer('Alertas del negocio',`<h2>Inventario por reponer</h2>${low.map(p=>`<div class="detail-row"><span>${esc(p.name)}</span><strong>${number(p.available)} ${p.unit}</strong></div>`).join('')||'<p class="subtitle">Sin alertas activas.</p>'}<h2 style="margin-top:24px">Vencimientos</h2>${lots.map(l=>`<div class="detail-row"><div><strong>${esc(product(l.product_id)?.name||'Producto')}</strong><p class="small muted">${number(l.remaining)} ${product(l.product_id)?.unit||''}</p></div><strong class="${l.expiry<dateKey()?'negative-text':''}">${dateLabel(dateAt(l.expiry))}</strong></div>`).join('')||'<p class="subtitle">No hay lotes próximos a vencer.</p>'}<h2 style="margin-top:24px">Pedidos pendientes</h2>${orders.map(o=>`<div class="detail-row"><span>P-${o.number} · ${esc(o.customer)}</span><button class="textbtn" onclick="orderDetail('${o.id}')">Revisar</button></div>`).join('')||'<p class="subtitle">No hay pedidos pendientes.</p>'}<div class="drawerfoot"><a class="btn" href="#ajustes" onclick="closeDrawer()">Configurar alertas</a><button class="btn primary" onclick="replenish()">Lista de compra</button></div>`)}
function downloadText(name,text,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function csvCell(v){let s=String(v??'');if(/^[=+@\-]/.test(s)&&typeof v!=='number')s="'"+s;return '"'+s.replaceAll('"','""')+'"'}
function csv(name,rows){downloadText(name,'\uFEFF'+rows.map(r=>r.map(csvCell).join(';')).join('\r\n'),'text/csv;charset=utf-8')}
function exportSales(){csv(`Verdelia-ventas-${from}-${to}.csv`,[['Operacion','Fecha Colombia','Hora Colombia','Tipo','Canal','Cliente','Medio','Subtotal','Descuento','Domicilio','Total','Costo historico','Ganancia bruta'],...filteredSales().map(s=>['VD-'+s.number,dateKey(s.created_at),timeLabel(s.created_at),s.type,s.channel,s.customer,methods[s.method],s.subtotal,s.discount,s.delivery,s.total,s.cost,Number(s.total)-Number(s.cost)])])}
function exportCash(){csv(`Verdelia-caja-${from}-${to}.csv`,[['Fecha','Hora Colombia','Tipo','Concepto','Medio','Valor'],...state.cash.map(c=>[dateKey(c.created_at),timeLabel(c.created_at),c.kind,c.note,methods[c.method],c.amount])])}
function exportReplenishment(){csv('Verdelia-lista-de-compra.csv',[['Producto','Categoria','Comprar','Unidad','Costo promedio','Inversion estimada'],...stockLow().map(p=>[p.name,p.category,Math.max(0,p.target-p.available),p.unit,p.avg_cost,Math.max(0,p.target-p.available)*p.avg_cost])])}
async function shareReceipt(raw){const s=JSON.parse(raw);const text=`${state.settings.name} · VD-${s.number}\n${dateLabel(s.created_at)} ${timeLabel(s.created_at)}\n${s.lines.map(l=>`${number(l.quantity)} ${l.unit} ${l.name}: ${money(l.subtotal)}`).join('\n')}\nTotal: ${money(s.total)}\nPago: ${methods[s.method]}\nComprobante de control interno.`;try{if(navigator.share)await navigator.share({title:'Comprobante Verdélia',text});else{await navigator.clipboard.writeText(text);toast('Comprobante copiado.')}}catch(e){if(e.name!=='AbortError')toast('No se pudo compartir. Puedes usar Imprimir / PDF.')}}
function publicUrl(hash='tienda'){return location.origin+location.pathname+'#'+hash}
async function shareCatalog(){const url=publicUrl();try{if(navigator.share)await navigator.share({title:'Verdélia · Link de venta',text:'Haz tu pedido de frutas, verduras y minimarket.',url});else{await navigator.clipboard.writeText(url);toast('Link de venta copiado.')}}catch(e){if(e.name!=='AbortError')toast('Copia el enlace que aparece en pantalla.')}}
function storeView(){const publicMode=page==='tienda',cs=catalog.settings,ps=catalog.products||[],cats=[...new Set([...categories,...ps.map(p=>p.category)])],items=ps.filter(p=>(storeCategory==='Todos'||p.category===storeCategory)&&p.name.toLowerCase().includes(storeQuery.toLowerCase()));return `${!publicMode?header('Link de venta','Todos tus productos publicados, organizados por categoría.',`<button class="btn" onclick="shareCatalog()">Compartir link</button><a class="btn primary" href="#tienda">Ver como cliente ${icon('diagonal')}</a>`):''}${!publicMode?`<div class="link-row">${icon('link')}<input readonly aria-label="Link de venta" value="${esc(publicUrl())}"><button class="btn" onclick="shareCatalog()">Copiar / compartir</button></div>`:''}<section class="store-banner" style="margin-top:20px"><div><div class="eyebrow">${esc(cs.name||'Verdélia')} · Fruver & minimarket</div><h2>Todo lo fresco.<br>Todo lo que necesitas.</h2><p>Arma tu pedido y confírmalo con nosotros por WhatsApp.</p></div><svg aria-hidden="true"><use href="#fruit-art"/></svg></section>${!cs.catalog_enabled?empty('Por ahora no recibimos pedidos','Vuelve más tarde o contáctanos por WhatsApp.',`<a class="btn primary" href="https://wa.me/${esc(cs.whatsapp||'573115565525')}" target="_blank" rel="noopener noreferrer">Hablar con Verdélia</a>`):`<div class="store-layout"><div><div class="toolbar"><label class="search">${icon('search')}<input aria-label="Buscar en el catálogo" placeholder="Buscar frutas, lácteos, limpieza…" value="${esc(storeQuery)}" oninput="storeQuery=this.value;updateStoreProducts()"></label><span class="small muted">${ps.length} productos</span></div><div class="store-category" aria-label="Categorías del catálogo">${['Todos',...cats].map(c=>`<button class="${c===storeCategory?'active':''}" data-category="${esc(c)}" onclick="storeCategory=this.dataset.category;render()">${esc(c)}</button>`).join('')}</div><div id="store-products">${storeProducts(items)}</div></div><aside class="card cart" id="cart-panel">${cartPanel()}</aside></div>`}`}
function storeProducts(items){if(!items.length)return empty('No encontramos productos',storeCategory!=='Todos'?'Todavía no hay productos publicados en esta categoría.':catalog.products.length?'Prueba otra búsqueda o categoría.':'Verdélia está preparando su catálogo. Pronto encontrarás los productos aquí.');return `<div class="store-grid">${items.map(p=>`<article class="store-product"><div class="product-art">${p.image_url?`<img src="${esc(p.image_url)}" alt="${esc(p.name)}" width="300" height="220" loading="lazy">`:`<div style="text-align:center"><svg style="width:70px;height:65px;color:#6f8b4f"><use href="${p.kind==='combo'?'#fruit-art':'#i-box'}"/></svg><p class="small muted">${esc(p.category)}</p></div>`}</div><div><h3>${esc(p.name)}</h3><p>${esc(p.description||p.category)}</p><div class="between"><strong class="catalog-price">${money(p.price)} <span class="small muted">/ ${p.unit}</span></strong><button class="btn" onclick="cartAdd('${p.id}')" ${p.available<=0?'disabled':''} aria-label="Agregar ${esc(p.name)}">${p.available<=0?'Agotado':icon('plus')+' Añadir'}</button></div>${p.unit==='kg'?'<p class="stock-label">Puedes pedir en kilos, libras o gramos.</p>':''}</div></article>`).join('')}</div>`}
function updateStoreProducts(){$('#store-products').innerHTML=storeProducts(catalog.products.filter(p=>(storeCategory==='Todos'||p.category===storeCategory)&&p.name.toLowerCase().includes(storeQuery.toLowerCase())))}
const catalogProduct=id=>catalog.products.find(p=>p.id===id);
const catalogFactor=(p,u)=>p.unit==='kg'?(u==='lb'?Number(catalog.settings.pound_grams)/1000:u==='g'?.001:1):1;
const cartSubtotal=()=>cart.reduce((n,l)=>{const p=catalogProduct(l.id);return n+(p?Math.round(p.price*catalogFactor(p,l.unit)*l.quantity*100)/100:0)},0);
function cartAdd(id){const p=catalogProduct(id),l=cart.find(l=>l.id===id&&l.unit===p.unit);if(l)l.quantity+=1;else cart.push({id,quantity:1,unit:p.unit});$('#cart-panel').innerHTML=cartPanel();toast('Producto añadido al pedido.')}
function cartPanel(){cart=cart.filter(l=>catalogProduct(l.id));return `<div class="cardhead"><h2 class="label-icon">${icon('bag')}Tu pedido</h2>${badge(cart.length)}</div>${cart.length?cart.map((l,i)=>{const p=catalogProduct(l.id);return `<div class="cart-item" style="flex-wrap:wrap"><div class="grow"><p>${esc(p.name)}</p><small>${money(p.price*catalogFactor(p,l.unit)*l.quantity)}</small></div><button class="textbtn" aria-label="Quitar ${esc(p.name)}" onclick="cart.splice(${i},1);$('#cart-panel').innerHTML=cartPanel()">${icon('close')}</button><div class="flex" style="width:100%"><label class="sr-only" for="cartqty-${i}">Cantidad de ${esc(p.name)}</label><input id="cartqty-${i}" class="inline-input" type="number" min="0.001" step="${p.unit==='kg'||p.unit==='litro'?'0.001':'1'}" value="${l.quantity}" onchange="cart[${i}].quantity=Number(this.value);$('#cart-panel').innerHTML=cartPanel()"><select class="select" aria-label="Medida de ${esc(p.name)}" onchange="cart[${i}].unit=this.value;$('#cart-panel').innerHTML=cartPanel()">${(p.unit==='kg'?['kg','lb','g']:[p.unit]).map(u=>`<option ${u===l.unit?'selected':''}>${u}</option>`).join('')}</select></div></div>`}).join(''):'<div class="cart-empty">Elige tus favoritos.<br><span class="small">Tu pedido aparecerá aquí.</span></div>'}<div class="cart-total between"><span>Subtotal</span><strong>${money(cartSubtotal())}</strong></div><button class="btn primary" onclick="checkout()" ${cart.length?'':'disabled'}>Continuar pedido ${icon('arrow')}</button><p class="cart-note">El peso y la disponibilidad se confirman antes de preparar.</p>`}
function checkout(){cart=cart.map((l,i)=>({...l,quantity:Number($('#cartqty-'+i).value)}));if(!cart.length||cart.some(l=>!Number.isFinite(l.quantity)||l.quantity<=0)){toast('Revisa las cantidades de tu pedido.');return}const options=[];if(catalog.settings.pickup_enabled)options.push(['pickup','Recoger en el local']);if(catalog.settings.delivery_enabled)options.push(['delivery','Domicilio · '+money(catalog.settings.delivery_fee)]);if(!options.length){toast('No hay modalidades de entrega disponibles. Contacta a Verdélia.');return}openDrawer('Completa tu pedido',`<form onsubmit="placeOrder(event)">${field('Tu nombre','customer','text','','required minlength="2" maxlength="100" autocomplete="name"')}${field('Teléfono / WhatsApp','phone','tel','','required minlength="7" maxlength="20" autocomplete="tel"')}${selectField('Cómo lo recibes','delivery_type',options,options[0][0],`onchange="$('#delivery-address').hidden=this.value!=='delivery';$('#delivery-address input').required=this.value==='delivery'"`)}<div id="delivery-address" ${options[0][0]==='delivery'?'':'hidden'}>${field('Dirección','address','text','','maxlength="250" autocomplete="street-address" '+(options[0][0]==='delivery'?'required minlength="5"':''))}</div>${field('Notas (opcional)','note','text','','maxlength="500"')}<label hidden>Website<input name="website" tabindex="-1" autocomplete="off"></label><div class="detail-row"><span>Subtotal de productos</span><strong>${money(cartSubtotal())}</strong></div><p class="small muted" style="margin-top:12px">Guardaremos estos datos para gestionar tu pedido. Después podrás enviar el resumen por WhatsApp.</p>${buttons('Guardar pedido y preparar WhatsApp')}</form>`)}
async function placeOrder(e){e.preventDefault();if(requestInFlight)return;const f=e.target;requestInFlight=true;f.classList.add('busy');try{const request_id=f.dataset.requestId||=crypto.randomUUID(),data={...formData(f),lines:cart,request_id},r=await rpc('verdelia_order',{data});const message=`Hola, ${catalog.settings.name}. Mi pedido es P-${r.number}:\n\n${r.quote.lines.map(l=>`${number(l.quantity)} ${l.unit} ${l.name} — ${money(l.subtotal)}`).join('\n')}\n\nDomicilio: ${money(r.quote.delivery)}\nTotal estimado: ${money(r.quote.total)}\nEntrega: ${data.delivery_type==='pickup'?'Recogida en el local':data.address}\nNombre: ${data.customer}\nTeléfono: ${data.phone}${data.note?'\nNota: '+data.note:''}\n\nPor favor confirmen disponibilidad y total final.`;cart=[];requestInFlight=false;render();openDrawer('Pedido P-'+r.number+' guardado',`<div class="banner">${icon('check')}Tu pedido quedó pendiente de confirmación.</div><p class="desc">Ahora envía el resumen por WhatsApp para coordinar con Verdélia.</p><div class="message-preview" style="margin-top:20px">${esc(message)}</div><div class="drawerfoot"><a class="btn primary" href="https://wa.me/${encodeURIComponent(catalog.settings.whatsapp)}?text=${encodeURIComponent(message)}" target="_blank" rel="noopener noreferrer">Abrir WhatsApp ${icon('diagonal')}</a></div><p class="status-line">Al abrir WhatsApp, pulsa Enviar. Guardar este pedido no significa que esté pagado.</p>`)}catch(err){showError(err)}finally{requestInFlight=false;f.classList.remove('busy')}}
function settingsView(){const s=state.settings,p=state.preferences;return `${header('Ajustes y automatizaciones','Configura el negocio y los accesos rápidos para tu iPhone.')}<div class="cash-layout"><section class="card"><h2>Datos de Verdélia</h2><form style="margin-top:18px" onsubmit="settingsSubmit(event)">${field('Nombre del negocio','name','text',s.name,'required maxlength="100"')}${field('WhatsApp con código de país','whatsapp','tel',s.whatsapp,'required pattern="[0-9]{7,15}"')}${field('Dirección del local','address','text',s.address,'maxlength="250"')}${selectField('Una libra equivale a','pound_grams',[['500','500 gramos'],['453.592','453,592 gramos']],String(s.pound_grams))}${field('Domicilio base (COP)','delivery_fee','number',s.delivery_fee,'required min="0" step="1"')}${field('Hora habitual de cierre','closing_time','time',s.closing_time.slice(0,5),'required')}${check('Recogida en el local','pickup_enabled',s.pickup_enabled)}${check('Domicilios','delivery_enabled',s.delivery_enabled)}${check('Catálogo abierto a pedidos','catalog_enabled',s.catalog_enabled)}<label class="field">Información para el cliente<textarea name="notes" maxlength="1000">${esc(s.notes)}</textarea></label><button class="btn primary" type="submit">Guardar ajustes</button></form></section><div><section class="card"><h2>Qué avisos recibir</h2><form style="margin-top:17px" onsubmit="preferencesSubmit(event)">${check('Inventario bajo o agotado','stock',p.stock)}${check('Lotes próximos a vencer','expiry',p.expiry)}${check('Pedidos pendientes','pending_orders',p.pending_orders)}${field('Días de anticipación del vencimiento','expiry_days','number',p.expiry_days??3,'required min="0" max="30" step="1"')}<button class="btn primary" type="submit">Guardar alertas</button></form><p class="status-line">Pedidos e inventario también se envían a tus dispositivos activados. Los vencimientos aparecen en el panel.</p></section><section class="card" style="margin-top:15px"><h2>Tu cuenta</h2><div class="detail-row"><span>Usuario</span><strong>verdelia</strong></div><div class="detail-row"><span>Correo del administrador</span><strong style="font-size:11px">${esc(state.account?.email||'Configurado en tu cuenta')}</strong></div><div class="support-links"><button class="textbtn" onclick="passwordForm()">Cambiar contraseña</button><button class="textbtn" onclick="downloadBackup()">Exportar período</button><button class="textbtn" onclick="auditDrawer()">Historial de cambios</button></div><p class="status-line">La recuperación se hace con tu código privado; no se envían correos automáticos.</p></section></div></div><div class="row2" style="margin-top:20px"><section class="card" id="push-settings"><h2>Notificaciones en tus dispositivos</h2><p class="status-line">Consultando estado…</p></section><section class="card" id="backup-settings"><h2>Respaldos automáticos</h2><p class="status-line">Consultando estado…</p></section></div><h2 style="font-size:20px;margin:30px 0 17px">Verdélia en tu iPhone</h2><div class="automation-grid"><section class="card automation-card">${badge('Disponible','positive')}<h2>Instalar como web/app</h2><p>Abre este enlace en Safari, pulsa Compartir y Añadir a pantalla de inicio. Tendrás el ícono de Verdélia y una ventana propia.</p><button class="btn" onclick="copyText(publicUrl('resumen'))">Copiar enlace de la app</button></section><section class="card automation-card">${badge('Configurar en el iPhone','warning')}<h2>Accesos con Atajos, Siri o NFC</h2><p>Crea un atajo con la acción Abrir URLs y usa uno de estos enlaces. Después puedes vincularlo a Siri, una etiqueta NFC o el botón Acción compatible.</p><div class="flex wrap"><button class="btn" onclick="copyText(publicUrl('resumen?accion=venta'))">Nueva venta</button><button class="btn" onclick="copyText(publicUrl('caja?accion=gasto'))">Registrar gasto</button><button class="btn" onclick="copyText(publicUrl('caja?accion=cierre'))">Cerrar caja</button><button class="btn" onclick="copyText(publicUrl('inventario?accion=reposicion'))">Reposición</button></div><p class="status-line">Cada botón copia el enlace. No instala ni activa Atajos automáticamente.</p></section><section class="card automation-card">${badge('Archivo listo para importar','positive')}<h2>Recordatorio diario de cierre</h2><p>Descarga un evento recurrente para tu calendario a las ${esc(s.closing_time.slice(0,5))}, con aviso 15 minutos antes. Revísalo e impórtalo en el iPhone.</p><button class="btn" onclick="downloadReminder()">${icon('download')}Descargar recordatorio</button></section><section class="card automation-card">${badge('Disponible','positive')}<h2>Compartir e imprimir comprobantes</h2><p>Abre una venta para compartir el resumen o imprimir / guardar PDF. En iPhone, AirPrint necesita una impresora compatible. Una térmica Bluetooth puede requerir su propia aplicación.</p><a class="btn" href="#ventas">Ir a ventas ${icon('arrow')}</a></section><section class="card automation-card">${badge('Disponible','positive')}<h2>Compartir tu Link de venta</h2><p>Envía el catálogo por WhatsApp o cualquier aplicación compatible. Los clientes pueden buscar y filtrar todos los productos publicados por categoría.</p><button class="btn" onclick="shareCatalog()">Compartir catálogo ${icon('link')}</button></section></div><p class="subtitle" style="margin-top:20px">La aplicación necesita internet para consultar o registrar operaciones. Si se corta la conexión, no se guardan ventas silenciosamente.</p>`}
async function settingsSubmit(e){e.preventDefault();const f=e.target,d=formData(f);for(const k of ['delivery_enabled','pickup_enabled','catalog_enabled'])d[k]=f.elements[k].checked;if(!d.delivery_enabled&&!d.pickup_enabled){toast('Activa al menos una modalidad de entrega.');return}await mutate('settings',d,f);loadAutomation()}
async function preferencesSubmit(e){e.preventDefault();const f=e.target,d=formData(f);for(const k of ['stock','expiry','pending_orders'])d[k]=f.elements[k].checked;await mutate('preferences',d,f);loadAutomation()}
async function copyText(s){try{await navigator.clipboard.writeText(s);toast('Enlace copiado.')}catch{openDrawer('Copia este enlace',`<input class="select full" readonly value="${esc(s)}" onclick="this.select()">`)}}
function downloadReminder(){const dt=dateKey().replaceAll('-',''),time=state.settings.closing_time.slice(0,5).replace(':','')+'00',stamp=new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');const text=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Verdelia//Cierre de caja//ES','CALSCALE:GREGORIAN','BEGIN:VEVENT','UID:verdelia-cierre-'+crypto.randomUUID(),'DTSTAMP:'+stamp,'DTSTART;TZID=America/Bogota:'+dt+'T'+time,'DURATION:PT15M','RRULE:FREQ=DAILY','SUMMARY:Cerrar caja de Verdelia','DESCRIPTION:Revisar ventas y contar efectivo. '+publicUrl('caja?accion=cierre'),'BEGIN:VALARM','ACTION:DISPLAY','DESCRIPTION:Cierre de caja Verdelia','TRIGGER:-PT15M','END:VALARM','END:VEVENT','END:VCALENDAR'].join('\r\n');downloadText('Verdelia-cierre-diario.ics',text,'text/calendar;charset=utf-8')}
function downloadBackup(){downloadText('Verdelia-datos-'+dateKey()+'.json',JSON.stringify({exported_at:new Date().toISOString(),period:{from,to},...state},null,2),'application/json');toast('Descarga del período consultado. Guarda el archivo en un lugar privado.')}
function auditDrawer(){openDrawer('Historial de cambios',`<p class="desc">Últimas 200 acciones. Las operaciones financieras conservan sus propios comprobantes.</p>${state.audit.map(a=>`<div class="history-item"><p>${esc(({product_correction:'Costo o medida corregidos',save_product:'Producto actualizado',sale:'Venta registrada',receive:'Compra recibida',adjust_stock:'Inventario ajustado',cash:'Movimiento de caja',close_cash:'Caja cerrada',confirm_order:'Pedido confirmado',cancel_order:'Pedido cancelado',complete_order:'Pedido entregado',refund:'Devolución registrada',settings:'Ajustes actualizados',preferences:'Alertas actualizadas',order_created:'Pedido recibido',auth_login:'Inicio de sesión',auth_activate:'Cuenta activada',auth_recover:'Acceso recuperado',auth_change_password:'Contraseña cambiada'})[a.action]||a.action)}</p><small>${dateLabel(a.created_at)} · ${timeLabel(a.created_at)}</small>${a.detail?.note?`<p class="small muted">${esc(a.detail.note)}</p>`:''}${a.action==='product_correction'?`<p class="small muted">Costo: ${money(a.detail.old_cost)} / ${esc(a.detail.old_unit)} → ${money(a.detail.new_cost)} / ${esc(a.detail.new_unit)}</p>`:''}</div>`).join('')||'<p class="subtitle">Sin actividad registrada.</p>'}`)}
function passwordForm(){openDrawer('Cambiar contraseña',`<form onsubmit="changePassword(event)">${field('Contraseña actual','old_password','password','','required autocomplete="current-password"')}${field('Nueva contraseña','password','password','','required minlength="10" autocomplete="new-password"')}${field('Repite la nueva contraseña','confirm','password','','required minlength="10" autocomplete="new-password"')}<p class="small muted">Se cerrarán las otras sesiones y recibirás un código de recuperación nuevo.</p>${buttons('Cambiar contraseña')}</form>`)}
async function changePassword(e){e.preventDefault();const d=formData(e.target);if(d.password!==d.confirm){toast('Las contraseñas no coinciden.');return}try{const r=await rpc('verdelia_login',{action:'change_password',data:{...d,session}});session=r.session;localStorage.setItem('verdelia.session',session);showRecovery(r.recovery_code)}catch(e){showError(e)}}
let automationState=null,automationBusy=false;
const automationCall=(action,data={})=>rpc('verdelia_automation',{action,data:{...data,session}});
function iphoneNeedsInstall(){return /iPad|iPhone|iPod/.test(navigator.userAgent)&&!window.matchMedia('(display-mode: standalone)').matches&&!navigator.standalone}
async function loadAutomation(){
 if(!session||page!=='ajustes')return;
 try{automationState=await automationCall('status');renderAutomation()}catch(e){for(const id of ['push-settings','backup-settings']){const el=$('#'+id);if(el)el.innerHTML=`<h2>${id==='push-settings'?'Notificaciones':'Respaldos'}</h2><p class="status-line">${esc(e.message)}</p><button class="btn" onclick="loadAutomation()">Reintentar</button>`}}
}
function renderAutomation(){
 if(!automationState||!$('#push-settings'))return;
 const a=automationState,id=localStorage.getItem('verdelia.pushDevice'),device=a.devices.find(d=>d.id===id),installed=!iphoneNeedsInstall(),supported='serviceWorker' in navigator&&'PushManager' in window&&'Notification' in window;
 const permission=supported?Notification.permission:'unsupported';
 $('#push-settings').innerHTML=`<div class="cardhead"><h2>Notificaciones</h2>${badge(device&&permission==='granted'?'Activadas aquí':'Por activar',device&&permission==='granted'?'positive':'neutral')}</div><p class="small muted">Pedidos nuevos y productos que llegan al mínimo o se agotan. Funciona con la app cerrada.</p>${!installed?'<div class="banner" style="margin-top:16px">En Safari: Compartir → Añadir a pantalla de inicio. Abre Verdélia desde su ícono y vuelve aquí.</div>':!supported?'<p class="status-line">Este navegador no admite notificaciones. En iPhone necesitas iOS 16.4 o posterior y la app instalada.</p>':permission==='denied'?'<p class="status-line">El permiso está bloqueado. Actívalo en Ajustes del iPhone → Notificaciones → Verdélia y vuelve a intentarlo.</p>':''}<div class="flex wrap" style="margin-top:16px">${device?`<button class="btn" onclick="testPush()">Enviar prueba</button><button class="textbtn" onclick="removePushDevice('${device.id}')">Desactivar aquí</button>`:`<button class="btn primary" onclick="enablePush()" ${!installed||!supported||permission==='denied'||!a.public_key?'disabled':''}>Activar en este dispositivo</button>`}<button class="textbtn" onclick="loadAutomation()">Actualizar estado</button></div>${a.devices.length?`<div style="margin-top:16px">${a.devices.map(d=>`<div class="detail-row"><span>${esc(d.label)}${d.id===id?' · Este dispositivo':''}</span>${d.id!==id?`<button class="textbtn" onclick="removePushDevice('${d.id}')">Desactivar</button>`:''}</div>`).join('')}</div>`:''}<p class="status-line">El inventario se revisa cada minuto. Se avisa al cambiar a stock bajo o agotado, sin repetirlo continuamente. Los modos de concentración pueden silenciar avisos.</p>${a.delivery?.failed?'<p class="form-error">Hubo avisos sin entregar. Prueba la conexión o reactiva el dispositivo.</p>':''}`;
 const last=a.backups.find(b=>b.status==='completed'),current=a.backups[0];
 $('#backup-settings').innerHTML=`<div class="cardhead"><h2>Respaldos automáticos</h2>${badge(current?.status==='failed'?'Requiere revisión':last?'Activo':'Preparando',current?.status==='failed'?'danger':last?'positive':'neutral')}</div><div class="detail-row"><span>Frecuencia</span><strong>Diario · 2:00 a. m.</strong></div><div class="detail-row"><span>Conservación</span><strong>30 días</strong></div><div class="detail-row"><span>Última copia verificada</span><strong class="small">${last?dateLabel(last.completed_at)+' · '+timeLabel(last.completed_at):'Aún no disponible'}</strong></div><p class="small muted">Hora de Colombia. Incluye todo el historial: productos, recetas, ventas, pedidos, compras, caja y ajustes.</p>${current&&['pending','running'].includes(current.status)?'<p class="status-line">Hay un respaldo en proceso. El estado se actualizará automáticamente.</p>':''}${current?.status==='failed'?'<p class="form-error">El último respaldo falló después de tres intentos. Conservamos las copias anteriores.</p>':''}<div class="flex wrap" style="margin-top:16px"><button class="btn" onclick="requestBackup()">Respaldar ahora</button>${last?`<button class="btn" onclick="downloadFullBackup('${last.id}')">Descargar último</button>`:''}<button class="textbtn" onclick="backupHistory()">Ver copias</button></div><p class="status-line">Copias privadas en Supabase, fuera de las tablas de trabajo. No incluyen contraseñas. Descarga una copia para guardarla también fuera de Supabase.</p>`;
}
async function enablePush(){
 if(automationBusy)return;
 if(iphoneNeedsInstall()){toast('Abre Verdélia desde el ícono de la pantalla de inicio.');return}
 if(!automationState?.public_key){toast('Actualiza el estado y vuelve a intentarlo.');return}
 automationBusy=true;
 try{
  // Permission must be requested directly from this user gesture on iOS.
  const permission=await Notification.requestPermission();
  if(permission!=='granted'){toast('No se activaron las notificaciones. Puedes intentarlo de nuevo desde Ajustes.');return}
  const registration=await navigator.serviceWorker.register('./sw.js');await navigator.serviceWorker.ready;
  const bytes=Uint8Array.from(atob(automationState.public_key.replace(/-/g,'+').replace(/_/g,'/')),c=>c.charCodeAt(0));
  const subscription=await registration.pushManager.getSubscription()||await registration.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:bytes});
  const label=/iPhone/.test(navigator.userAgent)?'Mi iPhone':/iPad/.test(navigator.userAgent)?'Mi iPad':/Mac/.test(navigator.userAgent)?'Mi Mac':'Mi computador';
  const r=await automationCall('subscribe',{subscription:subscription.toJSON(),label});localStorage.setItem('verdelia.pushDevice',r.id);
  toast('Activadas. Enviamos una notificación de bienvenida.');await loadAutomation();
 }catch(e){toast('No se pudieron activar: '+e.message)}finally{automationBusy=false}
}
async function removePushDevice(id){try{await automationCall('unsubscribe',{id});if(id===localStorage.getItem('verdelia.pushDevice')){localStorage.removeItem('verdelia.pushDevice');const r=await navigator.serviceWorker.getRegistration();await(await r?.pushManager.getSubscription())?.unsubscribe()}toast('Notificaciones desactivadas en ese dispositivo.');await loadAutomation()}catch(e){showError(e)}}
async function testPush(){try{await automationCall('test',{id:localStorage.getItem('verdelia.pushDevice')});toast('Prueba en cola. Revisa las notificaciones del dispositivo.')}catch(e){showError(e)}}
async function requestBackup(){if(automationBusy)return;automationBusy=true;try{await automationCall('backup');toast('Respaldo solicitado. Puedes seguir usando Verdélia.');await loadAutomation();setTimeout(loadAutomation,6000)}catch(e){showError(e)}finally{automationBusy=false}}
async function downloadFullBackup(id){try{const r=await fetch(cfg.url+'/functions/v1/verdelia-automation',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'download',id,session})});const d=await r.json();if(!r.ok)throw new Error(d.error||'No se pudo descargar.');const a=document.createElement('a');a.href=d.url;a.rel='noopener noreferrer';a.download='Verdelia-respaldo.json.gz';a.click();toast('Descargando copia completa. Guárdala en un lugar privado.')}catch(e){showError(e)}}
function backupHistory(){if(!automationState)return;openDrawer('Copias de respaldo',`<p class="desc">Copias completas de los últimos 30 días. Cada copia se comprueba después de guardarla.</p>${automationState.backups.map(b=>`<div class="detail-row"><div><strong>${dateLabel(b.created_at)}</strong><p class="small muted">${timeLabel(b.created_at)} · ${{completed:'Verificada',pending:'Pendiente',running:'En proceso',failed:'Falló'}[b.status]||esc(b.status)}${b.bytes?' · '+Math.max(1,Math.round(b.bytes/1024))+' KB':''}</p></div>${b.status==='completed'?`<button class="textbtn" onclick="downloadFullBackup('${b.id}')">Descargar</button>`:''}</div>`).join('')||'<p class="status-line">Preparando la primera copia.</p>'}<p class="status-line">La restauración se realiza con asistencia para revisar la copia y evitar reemplazar datos por accidente.</p>`)}
setInterval(()=>{if(session&&page==='ajustes'&&!document.hidden&&!automationBusy)loadAutomation()},60000);
window.addEventListener('hashchange',route);offline();route();
let lastPending=null;
setInterval(async()=>{if(!session||document.hidden||requestInFlight||$('.drawer')||page==='tienda'||page==='activar'||page==='recuperar')return;try{const next=await rpc('verdelia_admin',{action:'snapshot',data:{session,from,to}}),n=next.orders.filter(o=>o.status==='pending').length;if(lastPending!==null&&n>lastPending)toast('Tienes un nuevo pedido pendiente.');lastPending=n;state=next;if(page==='calendario'){await calendarLoad();render()}else if(page!=='ajustes'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))render()}catch{}},60000);
if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
